def date_before_time_is_long_enough(
    text: str
) -> bool:
    """Check the slice up to the position found with ``find``."""
    position = text.find('T')
    if position == -1:
        return True
    return len(text[:position]) == 10


def time_after_date_is_long_enough(
    text: str
) -> bool:
    """
    Check the slice from the position after the one found with ``find``.
    """
    position = text.find('T')
    if position == -1:
        return True
    return len(text[position + 1:]) == 8


def month_is_september(
    text: str
) -> bool:
    """
    Check ``find`` with a start and the slice between the found positions.
    """
    first = text.find('-')
    if first == -1:
        return True
    second = text.find('-', first + 1)
    if second == -1:
        return False
    return text[first + 1:second] == '09'


def seconds_follow_colon(
    text: str
) -> bool:
    """Check the slices and ``find`` with negative literal positions."""
    position = text.find('T')
    if position == -1:
        return True
    return (
        (
            len(text) < 10
            or (
                (
                    text[-3:-2] == ':'
                    and text.find(':', -3) != -1
                    and len(text[:-9]) > 0
                )
            )
        ))


def last_character_is_not_z(
    text: str
) -> bool:
    """
    Check the positions computed at run time which are negative or out of range.

    The transpiled code needs to follow the Python semantics: a negative position
    counts from the end, and the positions out of range are clamped.
    """
    position = text.find('#')
    return (
        (
            text[position:] != 'Z'
            and text[-100:100] == text
            and text[3:1] == ''
            and text.find('', 100) == -1
            and text.find(text[position:], position) >= 0
        ))


def name_starts_with_prefix(
    name: str
) -> bool:
    """Check the slice of a constrained primitive with literal bounds."""
    return (
        (
            len(name) < 4
            or name[0:4] == 'name'
        ))


def name_has_no_space_after_prefix(
    name: str
) -> bool:
    """
    Check ``find`` on a constrained primitive and a slice with a literal start.
    """
    return (
        (
            len(name) < 4
            or name[4:].find(' ') == -1
        ))


def word_is_between_bounds(
    word: str
) -> bool:
    """Check the ordering of a string with the literals on both sides."""
    return (
        (
            'A' <= word
            and word < 'z'
        ))


def word_is_not_after_other_word(
    word: str,
    other_word: str
) -> bool:
    """Check the ordering of a constrained primitive with a string."""
    return (
        (
            (not (word > other_word))
            and other_word >= word
        ))


def word_sorts_before_replacement_character(
    word: str
) -> bool:
    """
    Check the ordering of a string with a character from U+E000 to U+FFFF.

    A character beyond the Basic Multilingual Plane such as "😀" (U+1F600) sorts
    after the replacement character (U+FFFD), but its UTF-16 code units (U+D83D and
    U+DE00) sort before it.
    """
    return word < '�'


def has_at_most_two_significant_decimals(
    amount: str
) -> bool:
    """
    Check ``rstrip`` on the fraction found with ``find`` and slicing.
    """
    position = amount.find('.')
    if position == -1:
        return True
    return len(amount[position + 1:].rstrip('0')) <= 2


def name_with_extension_is_short(
    name: str
) -> bool:
    """
    Check the concatenation assigned to the variables.

    We concatenate two literals on purpose, since C++ can not add two string
    literals natively.
    """
    extension = '.' + 'txt'
    path = name + extension
    return len(path) <= 12


class _Transformer(
        our_types.AbstractTransformer[
            Iterator[Error]
        ]
):
    # noinspection PyMethodMayBeStatic
    def transform_something(
            self,
            that: our_types.Something
    ) -> Iterator[Error]:
        if not (len(that.other_word + '😀') <= 3):
            yield Error(
                'Other word with an emoji must have at most three characters'
            )

        if not name_with_extension_is_short(that.name):
            yield Error(
                'Name with the extension must have at most 12 characters'
            )

        if not (not that.amount.startswith('+')):
            yield Error(
                'Amount must not start with a plus'
            )

        if not (not that.name.endswith('!')):
            yield Error(
                'Name must not end with an exclamation mark'
            )

        if not (that.other_word.rstrip('𐈀😁') == that.other_word):
            yield Error(
                'Other word must end neither with 𐈀 nor with 😁'
            )

        if not (that.amount.lstrip('0.') != ''):
            yield Error(
                'Amount must not be zero'
            )

        if not has_at_most_two_significant_decimals(that.amount):
            yield Error(
                'Amount must have at most two significant decimals'
            )

        if not (that.word < 'zzz'):
            yield Error(
                'Word must sort before zzz'
            )

        if not (
            word_sorts_before_replacement_character(
                that.other_word
            )
        ):
            yield Error(
                'Other word must sort before the replacement character'
            )

        if not (
            word_is_not_after_other_word(
                that.word,
                that.other_word
            )
        ):
            yield Error(
                'Word must not sort after the other word'
            )

        if not word_is_between_bounds(that.word):
            yield Error(
                'Word must be between A and z'
            )

        if not (
            not (len(that.text) >= 1)
            or (that.text[:1] != 'X')
        ):
            yield Error(
                'Text must not start with X'
            )

        if not name_has_no_space_after_prefix(that.name):
            yield Error(
                'Name must contain no space after the prefix'
            )

        if not name_starts_with_prefix(that.name):
            yield Error(
                'Name must start with the prefix'
            )

        if not last_character_is_not_z(that.text):
            yield Error(
                'Last character must not be Z'
            )

        if not seconds_follow_colon(that.text):
            yield Error(
                'Seconds must follow a colon'
            )

        if not month_is_september(that.text):
            yield Error(
                'Month must be September'
            )

        if not time_after_date_is_long_enough(that.text):
            yield Error(
                'Time after the date must have 8 characters'
            )

        if not date_before_time_is_long_enough(that.text):
            yield Error(
                'Date before the time must have 10 characters'
            )

        for error in verify_non_empty_string(that.name):
            error.path._prepend(
                PropertySegment(
                    that,
                    'name'
                )
            )
            yield error

        for error in verify_non_empty_string(that.word):
            error.path._prepend(
                PropertySegment(
                    that,
                    'word'
                )
            )
            yield error


_TRANSFORMER = _Transformer()


def verify(
        that: our_types.Class
) -> Iterator[Error]:
    """
    Verify the constraints of :paramref:`that` recursively.

    :param that: instance whose constraints we want to verify
    :yield: constraint violations
    """
    yield from _TRANSFORMER.transform(that)


def verify_non_empty_string(
        that: str
) -> Iterator[Error]:
    """Verify the constraints of :paramref:`that`."""
    if not (len(that) > 0):
        yield Error(
            'At least one character'
        )


